const fs = require('fs');
const buf = fs.readFileSync(0, 'utf8');
const len = buf.length;
let p = 0;

function readInt() {
  while (p < len) {
    const c = buf.charCodeAt(p);
    if (c >= 48 && c <= 57) break;
    p++;
  }
  let x = 0;
  while (p < len) {
    const c = buf.charCodeAt(p);
    if (c < 48 || c > 57) break;
    x = x * 10 + (c - 48);
    p++;
  }
  return x;
}

const N = readInt(), K = readInt(), U = readInt();

// pos[v] = posição (1-based) em que o número v é sorteado
const pos = new Int32Array(U + 1);
for (let i = 1; i <= U; i++) {
  pos[readInt()] = i;
}

// Para cada cartela, o instante em que é completada é o máximo
// das posições de sorteio dos seus números.
const times = new Int32Array(N);
let minT = 2147483647;
for (let c = 0; c < N; c++) {
  let t = 0;
  for (let j = 0; j < K; j++) {
    const q = pos[readInt()];
    if (q > t) t = q;
  }
  times[c] = t;
  if (t < minT) minT = t;
}

let out = '';
let first = true;
for (let c = 0; c < N; c++) {
  if (times[c] === minT) {
    if (!first) out += ' ';
    out += (c + 1);
    first = false;
  }
}
process.stdout.write(out + '\n');
